#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// C doesn't have async/await, use callbacks with threads
typedef struct {
    int user_id;
    void (*callback)(int user_id, char* result);
} request_t;

void* fetch_user_thread(void* arg) {
    request_t* req = (request_t*)arg;

    // Simulate async operation
    sleep(1);

    char* result = malloc(100);
    sprintf(result, "User %d data", req->user_id);

    req->callback(req->user_id, result);
    free(result);
    return NULL;
}

void on_user_fetched(int user_id, char* result) {
    printf("Fetched: %s\n", result);
}

void fetch_user_async(int user_id) {
    pthread_t thread;
    request_t* req = malloc(sizeof(request_t));
    req->user_id = user_id;
    req->callback = on_user_fetched;

    pthread_create(&thread, NULL, fetch_user_thread, req);
    pthread_detach(thread);
}

int main() {
    fetch_user_async(1);
    fetch_user_async(2);

    sleep(2); // Wait for async operations
    return 0;
}

