#include <iostream>
#include <future>
#include <chrono>
#include <thread>
#include <vector>

// Modern C++ async with std::future
struct User {
    int id;
    std::string name;
};

// Simulate async fetch
std::future<User> fetch_user_async(int user_id) {
    return std::async(std::launch::async, [user_id]() {
        // Simulate network delay
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        return User{user_id, "User" + std::to_string(user_id)};
    });
}

int main() {
    // Parallel execution
    auto future1 = fetch_user_async(1);
    auto future2 = fetch_user_async(2);

    // Wait for results
    auto user1 = future1.get();
    auto user2 = future2.get();

    std::cout << user1.name << ", " << user2.name << std::endl;

    return 0;
}
